/**
 * AD Sync Worker Lambda
 *
 * Receives { tenantId } from event (dispatched by ad-sync-dispatcher or manual invoke).
 * Loads tenant AD config from DynamoDB + credentials from Secrets Manager,
 * then runs a full batch sync against that tenant's Cognito User Pool.
 */

import { DynamoDBClient, GetItemCommand, QueryCommand, UpdateItemCommand } from '@aws-sdk/client-dynamodb';
import { SecretsManagerClient, GetSecretValueCommand } from '@aws-sdk/client-secrets-manager';
import { createRequire } from 'module';

const require = createRequire(import.meta.url);
const { buildConfig } = require('../../../../../CognitoAdSync/config');
const { runSyncWithConfig } = require('../../../../../CognitoAdSync/sync-engine');
const { createProvider } = require('../../../../../CognitoAdSync/providers');

const dynamodb = new DynamoDBClient({});
const secrets = new SecretsManagerClient({});

export const handler = async (event, context) => {
  const { tenantId } = event;
  console.log(JSON.stringify({ level: "DEBUG", event: "WORKER_INVOKED", tenantId, timestamp: new Date().toISOString() }));

  if (!tenantId) {
    console.error(JSON.stringify({ level: "ERROR", event: "MISSING_TENANT_ID", message: "tenantId required in event" }));
    return { statusCode: 400, body: { error: "tenantId required in event" } };
  }

  try {
    // 1. Load AD sync config from DynamoDB
    console.log(JSON.stringify({ level: "DEBUG", event: "LOADING_CONFIG", tenantId }));
    const configItem = await dynamodb.send(new GetItemCommand({
      TableName: process.env.CONFIG_TABLE,
      Key: { id: { S: tenantId }, configtype: { S: "adSyncConfig" } },
    }));

    if (!configItem.Item?.value?.S) {
      console.log(JSON.stringify({ level: "INFO", event: "NO_CONFIG", tenantId, message: "No AD sync config found" }));
      return { statusCode: 200, body: { skipped: true, reason: "no_config" } };
    }

    const adSyncConfig = JSON.parse(configItem.Item.value.S);

    if (!adSyncConfig.enabled) {
      console.log(JSON.stringify({ level: "INFO", event: "SYNC_DISABLED", tenantId }));
      return { statusCode: 200, body: { skipped: true, reason: "disabled" } };
    }

    // 2. Load tenant record for Cognito User Pool ID
    console.log(JSON.stringify({ level: "DEBUG", event: "LOADING_TENANT", tenantId }));
    const tenantResult = await dynamodb.send(new QueryCommand({
      TableName: process.env.TENANT_TABLE,
      KeyConditionExpression: "id = :id AND begins_with(sk, :sk_prefix)",
      ExpressionAttributeValues: {
        ":id": { S: `TENANT#${tenantId}` },
        ":sk_prefix": { S: "TENANT#" },
      },
      Limit: 1,
    }));

    const tenantItem = tenantResult.Items?.[0];
    if (!tenantItem?.userpool?.S) {
      console.error(JSON.stringify({ level: "ERROR", event: "TENANT_NOT_FOUND", tenantId, message: "Tenant or userpool not found" }));
      return { statusCode: 404, body: { error: "tenant_not_found" } };
    }

    const userPoolId = tenantItem.userpool.S;
    console.log(JSON.stringify({ level: "DEBUG", event: "TENANT_LOADED", tenantId, userPoolId }));

    // 3. Load AD credentials from Secrets Manager
    console.log(JSON.stringify({ level: "DEBUG", event: "LOADING_CREDENTIALS", tenantId }));
    const secretResponse = await secrets.send(new GetSecretValueCommand({
      SecretId: `apersona/${tenantId}/ad-sync`,
    }));
    const adCredentials = JSON.parse(secretResponse.SecretString);

    // 4. Build config for this tenant
    const config = buildConfig({
      tenantId,
      ldapProvider: adSyncConfig.ldapProvider,
      ldapUrl: adSyncConfig.ldapUrl,
      ldapBaseDN: adSyncConfig.ldapBaseDN,
      ldapPort: adSyncConfig.ldapPort,
      ldapBindDN: adCredentials.bindDN,
      ldapBindPassword: adCredentials.bindPassword,
      ldapGroupBaseDN: adSyncConfig.ldapGroupBaseDN,
      ldapTlsRejectUnauth: adSyncConfig.ldapTlsRejectUnauth,
      cognitoUserPoolId: userPoolId,
      syncS3Bucket: process.env.SYNC_STATE_BUCKET,
      syncBatchSize: adSyncConfig.syncBatchSize,
      deltaSyncEnabled: adSyncConfig.deltaSyncEnabled,
      fieldMappings: adSyncConfig.fieldMappings,
      logLevel: adSyncConfig.logLevel || "DEBUG",
    });

    console.log(JSON.stringify({
      level: "DEBUG", event: "CONFIG_BUILT", tenantId, userPoolId,
      ldapUrl: adSyncConfig.ldapUrl, ldapProvider: adSyncConfig.ldapProvider,
    }));

    // 4b. Handle test-connection action (invoked from adsyncconfig Lambda)
    if (event.action === 'test-connection') {
      console.log(JSON.stringify({ level: "INFO", event: "TEST_CONNECTION_START", tenantId }));
      const provider = createProvider(config);
      try {
        const client = await provider.getClient();
        const groups = await provider.fetchSecurityGroups();
        await provider.disconnect();
        console.log(JSON.stringify({ level: "INFO", event: "TEST_CONNECTION_SUCCESS", tenantId, groupCount: groups.length }));
        return {
          statusCode: 200,
          body: { success: true, tenantId, message: `Connected successfully. Found ${groups.length} security groups.` },
        };
      } catch (testErr) {
        await provider.disconnect().catch(() => {});
        console.error(JSON.stringify({ level: "ERROR", event: "TEST_CONNECTION_FAILED", tenantId, error: testErr.message }));
        return {
          statusCode: 200,
          body: { success: false, tenantId, error: testErr.message },
        };
      }
    }

    // 5. Run sync
    const state = await runSyncWithConfig(config, context);

    // 6. Update last sync status in DynamoDB
    const updatedConfig = {
      ...adSyncConfig,
      lastSyncStatus: state.status === "complete" ? "success" : "in_progress",
      lastSyncTime: new Date().toISOString(),
      lastSyncStats: state.stats,
    };

    await dynamodb.send(new UpdateItemCommand({
      TableName: process.env.CONFIG_TABLE,
      Key: { id: { S: tenantId }, configtype: { S: "adSyncConfig" } },
      UpdateExpression: "SET #val = :val",
      ExpressionAttributeNames: { "#val": "value" },
      ExpressionAttributeValues: { ":val": { S: JSON.stringify(updatedConfig) } },
    }));

    console.log(JSON.stringify({
      level: "INFO", event: "WORKER_COMPLETE", tenantId,
      syncId: state.syncId, status: state.status, stats: state.stats,
    }));

    return {
      statusCode: 200,
      body: { tenantId, syncId: state.syncId, status: state.status, stats: state.stats },
    };
  } catch (err) {
    console.error(JSON.stringify({
      level: "ERROR", event: "WORKER_FAILED", tenantId,
      error: err.message, stack: err.stack,
    }));

    // Update status to error
    try {
      const configItem = await dynamodb.send(new GetItemCommand({
        TableName: process.env.CONFIG_TABLE,
        Key: { id: { S: tenantId }, configtype: { S: "adSyncConfig" } },
      }));
      if (configItem.Item?.value?.S) {
        const adSyncConfig = JSON.parse(configItem.Item.value.S);
        adSyncConfig.lastSyncStatus = "error";
        adSyncConfig.lastSyncTime = new Date().toISOString();
        adSyncConfig.lastSyncError = err.message;
        await dynamodb.send(new UpdateItemCommand({
          TableName: process.env.CONFIG_TABLE,
          Key: { id: { S: tenantId }, configtype: { S: "adSyncConfig" } },
          UpdateExpression: "SET #val = :val",
          ExpressionAttributeNames: { "#val": "value" },
          ExpressionAttributeValues: { ":val": { S: JSON.stringify(adSyncConfig) } },
        }));
      }
    } catch (updateErr) {
      console.error(JSON.stringify({ level: "ERROR", event: "STATUS_UPDATE_FAILED", tenantId, error: updateErr.message }));
    }

    return { statusCode: 500, body: { error: err.message, tenantId } };
  }
};
